// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT.  Fork this workflow per agent: duplicate it,
//  change AGENT below, rewrite REMINDERS, rename the workflow, activate.
// ═══════════════════════════════════════════════════════════════════════

//  Which agent asks. Its Telegram bot sends the question and its voice is the
//  one you hear — 'atomix' for health, 'ultron' for academic, 'sentinel' for
//  money, 'speda' for everything else. The agent must have a bot token set and
//  you must have tapped /start on it.
const AGENT = 'atomix';

//  ── Fields ────────────────────────────────────────────────────────────
//  id             REQUIRED, stable. Renaming it starts a fresh reminder and
//                 loses the history attached to the old name.
//  text           REQUIRED. Sent verbatim — write it in the language you want
//                 to be asked in. No model rewrites it.
//  at             'HH:MM' wall clock, Europe/Istanbul (workflow Settings ▸
//                 Timezone). Omit for 'due whenever this workflow runs'.
//  days           '*' or weekday numbers, 1=Mon … 7=Sun. E.g. '1,2,3,4,5'.
//  options        The answer BUTTONS. label = what you see, value = what gets
//                 recorded in the history. First one should be the happy path.
//  every_minutes  How often it re-asks while unanswered. Default 5.
//  max_asks       How many times before it gives up and logs the day as
//                 missed. Default 10 — so 10 × 5 min ≈ 50 minutes of nagging.
//
const REMINDERS = [

  {
    id: 'medicine_morning',
    text: '💊 Sabah ilacını aldın mı?',
    at: '08:30',
    days: '*',
    options: [
      { label: '✅ Aldım',      value: 'taken' },
      { label: '⏭️ Atladım',    value: 'skipped' },
    ],
    every_minutes: 5,
    max_asks: 10,
  },

  // ── Add more below. Delete the example above once yours works. ────────
  // {
  //   id: 'water_evening',
  //   text: '💧 Bugün yeterince su içtin mi?',
  //   at: '21:00',
  //   options: [{ label: '✅ Evet', value: 'yes' }, { label: '❌ Hayır', value: 'no' }],
  //   every_minutes: 15, max_asks: 4,
  // },

];

// ── Nothing below this line needs editing ───────────────────────────────
const clean = REMINDERS.filter(r => r && r.id && r.text);
if (!clean.length) { return []; }   // empty list = do nothing, harmlessly
return [{ json: { agent: AGENT, reminders: clean }, pairedItem: { item: 0 } }];
